\documentclass[border = 5mm]{standalone}
\usepackage[dvipsnames]{xcolor}
\usepackage{tikz}
\usetikzlibrary{shapes,shadows,arrows}
\usepackage{tkz-euclide}
\usetkzobj{all}

\begin{document}
\pagestyle{empty}

\begin{tikzpicture}[scale=1.0, every node/.style={transform shape}]

\definecolor{deepskyblue}{rgb}{0.173,0.447,0.682}
\definecolor{orangepeel}{rgb}{0.902, 0.624, 0}
\definecolor{lightyellow}{rgb}{0.953,0.882,0.388}
\definecolor{darkgreen}{rgb}{0.271, 0.608, 0.463}
\definecolor{lightblue}{rgb}{0.484,0.702,0.894}
\definecolor{rustred}{rgb}{0.784,0.392,0.149}
\definecolor{fadedpink}{rgb}{0.753,0.494,0.643}

\def\mycolor{orangepeel}
\def\myfillopacity{0.25}

%%% Quadrilateral
\node[draw=none, fill=none] at (0,0) {Quadrilateral};

\draw[-, thick, shorten <    = 7mm, shorten > = 5mm] (0,0) -- (-4,-2);
\draw[-, thick, shorten <    = 3mm, shorten > = 3mm] (0,0) -- (0,-2);
\draw[-, thick, shorten <    = 7mm, shorten > = 5mm] (0,0) -- (4,-2); 

%%% =========
%%% Kite
\node[draw=none, fill=none, text centered, text width=7em] at (-4,-2) {Kite};
\begin{scope}[shift={(-4,-3.25)}, scale=0.75]
	\coordinate (A) at (0,1);
	\coordinate (B) at (0.75,0.25);
	\coordinate (C) at (0,-1);
	\coordinate (D) at (-0.75,0.25);

	\tkzDrawPolygon[draw=none, fill=\mycolor!25, fill opacity=\myfillopacity](A,B,C,D)
	\tkzDrawPolygon[thick, color=\mycolor](A,B,C,D)

	\tkzMarkSegments[mark=|, color=\mycolor](C,D B,C)
	\tkzMarkSegments[mark=||, color=\mycolor](A,D A,B) 
\end{scope}

\draw[-, thick, shorten <    = 23mm, shorten > = 3mm] (-4,-2) -- (-4,-5.5);
\draw[-, thick, shorten <    = 23mm, shorten > = 5mm] (0,-2) -- (-4,-5.5);

%%% Rhombus
\node[draw=none, fill=none, text centered, text width=7em] at (-4,-5.5) {Rhombus};
\begin{scope}[shift={(-4,-6.75)}, scale=0.75]
	\coordinate (A) at (0,1);
	\coordinate (B) at (0.75,0);
	\coordinate (C) at (0,-1);
	\coordinate (D) at (-0.75,0);

	\tkzDrawPolygon[draw=none, fill=\mycolor!25, fill opacity=\myfillopacity](A,B,C,D)
	\tkzDrawPolygon[thick, color=\mycolor](A,B,C,D)

	\tkzMarkSegments[mark=|, color=\mycolor](C,D B,C A,D A,B) 
\end{scope}

%%% =========
%%% Parallelogram
\node[draw=none, fill=none, text centered, text width=7em] at (0,-2) {Parallelogram};
\begin{scope}[shift={(-1,-3.25)}, scale=0.75]
	\coordinate (A) at (-0.5,-1);
	\coordinate (B) at (0,1);
	\coordinate (C) at (2.8,1);
	\coordinate (D) at (2.3,-1);

	\tkzDrawPolygon[draw=none, fill=\mycolor!25, fill opacity=\myfillopacity](A,B,C,D)
	\tkzDrawPolygon[thick, color=\mycolor](A,B,C,D)

	\begin{scope}[style={very thick},decoration={markings, mark=at position 0.5 with {\arrow[scale=1]{>}};}]
	\tkzDrawSegments[draw=none, color=\mycolor, postaction={decorate}](A,D B,C) 
	\end{scope}
	\begin{scope}[style={very thick},decoration={markings, mark=at position 0.6 with {\arrow[scale=1]{>>}};}]
	\tkzDrawSegments[draw=none, color=\mycolor, postaction={decorate}](A,B D,C) 
	\end{scope}
\end{scope}

\draw[-, thick, shorten <    = 23mm, shorten > = 3mm] (0,-2) -- (0,-5.5);

%%% Rectangle
\node[draw=none, fill=none, text centered, text width=7em] at (0,-5.5) {Rectangle};
\begin{scope}[shift={(-0.75,-6.75)}, scale=0.75]
	\coordinate (A) at (-0.5,-1);
	\coordinate (B) at (-0.5,1);
	\coordinate (C) at (2.5,1);
	\coordinate (D) at (2.5,-1);

	\tkzDrawPolygon[draw=none, fill=\mycolor!25, fill opacity=\myfillopacity](A,B,C,D)
	\tkzMarkRightAngles[draw=none, fill=\mycolor!50, size=0.5](A,B,C B,C,D C,D,A D,A,B)
	\tkzDrawPolygon[thick, color=\mycolor](A,B,C,D)

	\begin{scope}[style={very thick},decoration={markings, mark=at position 0.5 with {\arrow[scale=1]{>}};}]
	\tkzDrawSegments[draw=none, color=\mycolor, postaction={decorate}](A,D B,C) 
	\end{scope}
	\begin{scope}[style={very thick},decoration={markings, mark=at position 0.6 with {\arrow[scale=1]{>>}};}]
	\tkzDrawSegments[draw=none, color=\mycolor, postaction={decorate}](A,B D,C) 
	\end{scope}
\end{scope}

\draw[-, thick, shorten <    = 25mm, shorten > = 3mm] (0,-5.5) -- (-2,-9.5);
\draw[-, thick, shorten <    = 10mm, shorten > = 3mm] (-4,-6.5) -- (-2,-9.5);

%%% Square
\node[draw=none, fill=none, text centered, text width=7em] at (-2,-9.5) {Square};
\begin{scope}[shift={(-2.75,-10.75)}, scale=0.75]
	\coordinate (A) at (0,-1);
	\coordinate (B) at (0,1);
	\coordinate (C) at (2,1);
	\coordinate (D) at (2,-1);

	\tkzDrawPolygon[draw=none, fill=\mycolor!25, fill opacity=\myfillopacity](A,B,C,D)
	\tkzMarkRightAngles[draw=none, fill=\mycolor!50, size=0.5](A,B,C B,C,D C,D,A D,A,B)
	\tkzDrawPolygon[thick, color=\mycolor](A,B,C,D)

	\tkzMarkSegments[mark=|, color=\mycolor](C,D B,C A,D A,B) 
\end{scope}


%%% =========
%%% Trapezoid
\node[draw=none, fill=none, text centered, text width=7em, xshift=-5pt] at (4,-2) {Trapezoid};
\begin{scope}[shift={(3.25,-3.25)}, scale=0.75]
	\coordinate (A) at (-0.5,-1);
	\coordinate (B) at (0,1);
	\coordinate (C) at (1,1);
	\coordinate (D) at (2.5,-1);

	\tkzDrawPolygon[draw=none, fill=\mycolor!25, fill opacity=\myfillopacity](A,B,C,D)
	\tkzDrawPolygon[thick, color=\mycolor](A,B,C,D)

	\begin{scope}[style={very thick},decoration={markings, mark=at position 0.5 with {\arrow[scale=1]{>}};}]
	\tkzDrawSegments[draw=none, color=\mycolor, postaction={decorate}](A,D B,C) 
	\end{scope}
\end{scope}

\draw[-, thick, shorten <    = 23mm, shorten > = 3mm] (4,-2) -- (4,-5.5);

%%% Isosceles Trapezoid
\node[draw=none, fill=none, text centered, text width=9em, xshift=3pt] at (4,-5.5) {Isosceles Trapezoid};
\begin{scope}[shift={(3.25,-6.75)}, scale=0.75]
	\coordinate (A) at (-0.5,-1);
	\coordinate (B) at (0.25,1);
	\coordinate (C) at (1.75,1);
	\coordinate (D) at (2.5,-1);

	\tkzDrawPolygon[draw=none, fill=\mycolor!25, fill opacity=\myfillopacity](A,B,C,D)
	\tkzDrawPolygon[thick, color=\mycolor](A,B,C,D)

	\tkzMarkSegments[mark=|, color=\mycolor](A,B C,D)

	\begin{scope}[style={very thick},decoration={markings, mark=at position 0.5 with {\arrow[scale=1]{>}};}]
	\tkzDrawSegments[draw=none, color=\mycolor, postaction={decorate}](A,D B,C) 
	\end{scope}
\end{scope}

\end{tikzpicture}
\end{document}

